func ResourceCloudBuildGitLabConfigFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("name", flattenCloudBuildGitLabConfigName(res["name"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("username", flattenCloudBuildGitLabConfigUsername(res["username"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("secrets", flattenCloudBuildGitLabConfigSecrets(res["secrets"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("create_time", flattenCloudBuildGitLabConfigCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("webhook_key", flattenCloudBuildGitLabConfigWebhookKey(res["webhookKey"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("connected_repositories", flattenCloudBuildGitLabConfigConnectedRepositories(res["connectedRepositories"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}
	if err = d.Set("enterprise_config", flattenCloudBuildGitLabConfigEnterpriseConfig(res["enterpriseConfig"], d, config)); err != nil {
		return fmt.Errorf("Error reading GitLabConfig: %s", err)
	}

	return nil
}
